Write pytest tests for a custom exception hierarchy: raise ValidationError when a user dict is missing the email key, and assert the exception type and payload.

class AppError(Exception):
    pass

class ValidationError(AppError):
    def __init__(self, field):
        self.field = field
        super().__init__(f'missing field: {field}')

def validate_user(user):
    if 'email' not in user:
        raise ValidationError('email')
    return user

output:
import pytest
from validation import AppError, ValidationError, validate_user

def test_valid_user_passes():
    user = {'email': 'a@b.c'}
    assert validate_user(user) is user

def test_missing_email_raises_validation_error():
    with pytest.raises(ValidationError) as exc_info:
        validate_user({'name': 'ann'})
    assert exc_info.value.field == 'email'
    assert isinstance(exc_info.value, AppError)

