Write pytest tests for get_nested that accepts None as the root and raises TypeError when traversing into a non-dict node.

def get_nested(data, path):
    node = data
    for part in path.split('.'):
        if not isinstance(node, dict):
            raise TypeError(f'not a dict at {part!r}')
        node = node.get(part)
        if node is None:
            return None
    return node

output:
import pytest
from nested import get_nested

def test_get_nested_normal():
    assert get_nested({'a': {'b': 3}}, 'a.b') == 3

def test_get_nested_none_root():
    assert get_nested(None, 'a') is None

def test_get_nested_missing_key():
    assert get_nested({'a': 1}, 'b') is None

def test_get_nested_traverses_non_dict():
    with pytest.raises(TypeError):
        get_nested({'a': 5}, 'a.b.c')

