Write pytest tests for parse_bool that treats 'true'/'false' case-insensitively and raises ValueError for anything else, including None.

def parse_bool(text):
    if not isinstance(text, str):
        raise ValueError(f'expected string, got {type(text).__name__}')
    lowered = text.strip().lower()
    if lowered == 'true':
        return True
    if lowered == 'false':
        return False
    raise ValueError(f'not a boolean: {text!r}')

