Write pytest tests for a bounded buffer: adding beyond capacity raises OverflowError and adding up to capacity succeeds.

class BoundedBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self.items = []
    def add(self, item):
        if len(self.items) >= self.capacity:
            raise OverflowError('buffer full')
        self.items.append(item)

